/**
 * Big number (spec/02 §3.6): [value] in display with tabular figures („5 / 8“) over [label] in caption textMuted; both
 * wrap whole at large text (§14.10).
 */
@Composable
fun SbBigNumber(value: String, label: String, modifier: Modifier = Modifier) {
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    Column(
        modifier.semantics(mergeDescendants = true) { },
        verticalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s1),
    ) {
        SbWrapText(value, ty.display.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings), c.text)
        SbWrapText(label, ty.caption, c.textMuted)
    }
}

/**
 * A big number in parts (§14.10): [lead] („noch“), then each number in display with tabular figures and its word in
 * label („38 Wochen 1 Tag“), one line that wraps between words; [label] in caption textMuted under it. One TalkBack
 * node that reads the sentence.
 */
@Composable
fun SbBigNumber(parts: List<Pair<String, String>>, modifier: Modifier = Modifier, lead: String? = null, label: String? = null) {
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    val word = SpanStyle(fontSize = ty.label.fontSize, fontWeight = ty.label.fontWeight, letterSpacing = ty.label.letterSpacing)
    val line = buildAnnotatedString {
        if (lead != null) withStyle(word) { append(lead) }
        parts.forEach { (number, unit) ->
            if (length > 0) append(" ")
            append(number)
            append("\u00A0")
            withStyle(word) { append(unit) }
        }
    }
    Column(
        modifier.semantics(mergeDescendants = true) { },
        verticalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s1),
    ) {
        SbWrapText(line, ty.display.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings), c.text)
        if (label != null) SbWrapText(label, ty.caption, c.textMuted)
    }
}

/** One stat (spec/02 §3.6): [label] („Serie“) and [value] („12 Tage“); [spark] = the sparkline after the number (G3a). */
@Immutable
data class SbStatItem(val label: String, val value: String, val spark: List<Float>? = null)

/**
 * Stats (spec/02 §3.6): flat columns at least 96 dp wide that wrap into rows (the web's `minmax(96px, 1fr)`), a 1 dp
 * border line at the start of every column but the first, 12 dp inside; no fill, no frame, no card. Label in caption
 * textMuted over the value in title with tabular figures; a stat with [SbStatItem.spark] shows [SbSparkline] after its
 * number. One TalkBack node per stat (the sparkline has none: the number says it).
 */
@Composable
fun SbStats(items: List<SbStatItem>, modifier: Modifier = Modifier) {
    require(items.isNotEmpty()) { "SbStats: no stats" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val measurer = rememberTextMeasurer()
    val value = ty.title.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    // D99 (1), (2): a column holds text, so it grows: at least 96 dp (the web's minmax(96px, 1fr)), else as wide as
    // the widest word of a label or value and the 12 dp at both sides, so no word breaks; fewer columns per row then
    val widest = remember(items, measurer, value) {
        items.maxOf { maxOf(measurer.sbWidestWord(it.label, ty.caption), measurer.sbWidestWord(it.value, value)) }
    }
    BoxWithConstraints(modifier.fillMaxWidth()) {
        val column = maxOf(t.space.s12 * 2, with(LocalDensity.current) { widest.toDp() } + t.space.s3 * 2)
        val perRow = (maxWidth / column).toInt().coerceIn(1, items.size)
        Column(verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
            items.chunked(perRow).forEachIndexed { r, row ->
                Row(
                    Modifier
                        .fillMaxWidth()
                        .drawBehind {
                            val hair = t.borderWidth.hairline.toPx()
                            val w = size.width / perRow
                            row.indices.forEach { k ->
                                if (r > 0 || k > 0) {
                                    val x = if (layoutDirection == LayoutDirection.Rtl) size.width - k * w - hair / 2f else k * w + hair / 2f
                                    drawLine(c.border, Offset(x, 0f), Offset(x, size.height), hair)
                                }
                            }
                        },
                ) {
                    row.forEachIndexed { k, item -> SbStatColumn(item, first = r == 0 && k == 0, Modifier.weight(1f)) }
                    repeat(perRow - row.size) { Spacer(Modifier.weight(1f)) }
                }
            }
        }
    }
}

/** One column of [SbStats]: no start padding for the first, else 12 dp at both sides. */
@Composable
private fun SbStatColumn(item: SbStatItem, first: Boolean, modifier: Modifier) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val value = ty.title.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    Column(
        modifier
            .padding(start = if (first) t.space.s0 else t.space.s3, end = t.space.s3)
            .semantics(mergeDescendants = true) { },
        verticalArrangement = Arrangement.spacedBy(t.space.s0_5),
    ) {
        SbWrapText(item.label, ty.caption, c.textMuted)
        val spark = item.spark
        if (spark == null) {
            SbWrapText(item.value, value, c.text)
        } else {
            SbFlowRow(
                horizontalArrangement = Arrangement.spacedBy(t.space.s3),
                verticalArrangement = Arrangement.spacedBy(t.space.s1),
            ) {
                SbWrapText(item.value, value, c.text, Modifier.align(Alignment.CenterVertically))
                SbSparkline(spark, Modifier.align(Alignment.CenterVertically))
            }
        }
    }
}

/**
 * Sparkline (G3a): 96 × 28 dp, the line in chartBar (2 dp, round joins and caps), the last point a dot of radius 3 dp
 * in chartBarCurrent, 3 dp in from the sides and 4 dp from top and bottom; no axis, no semantics. It shows the same
 * period as the label of its number and never stands without that number (use it through [SbStatItem.spark]).
 */
@Composable
fun SbSparkline(values: List<Float>, modifier: Modifier = Modifier) {
    require(values.size >= 2) { "SbSparkline: at least two values" }
    val t = SebaroTheme.tokens
    Canvas(modifier.size(t.space.s12 * 2, t.space.s6 + t.space.s1)) {
        val lo = values.min()
        val span = (values.max() - lo).takeIf { it > 0f } ?: 1f
        val dot = 3.dp.toPx()   // r 3, as the web's sb-sparkline__now
        val inset = t.space.s1.toPx()
        fun at(i: Int) = Offset(
            dot + (size.width - 2 * dot) * i / values.lastIndex,
            inset + (size.height - 2 * inset) * (1f - (values[i] - lo) / span),
        )
        val line = Path().apply {
            moveTo(at(0).x, at(0).y)
            for (i in 1..values.lastIndex) lineTo(at(i).x, at(i).y)
        }
        drawPath(line, t.x.chartBar, style = Stroke(width = t.x.chartLineWidth.toPx(), cap = StrokeCap.Round, join = StrokeJoin.Round))
        drawCircle(t.x.chartBarCurrent, radius = dot, center = at(values.lastIndex))
    }
}
